    Undefined();
elsif PSTATE.EL == EL0 then
    if EffectivelyAtEL0NotInHost() && SCTLR_EL1().EnFPM == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EffectivelyAtEL0InHost() && SCTLR_EL2().EnFPM == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && EffectivelyAtEL0NotInHost() && (!IsHCRXEL2Enabled() || HCRX_EL2().EnFPM == '0') then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif HaveEL(EL3) && SCR_EL3().EnFPM == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    elsif EffectivelyAtEL0NotInHost() && CPACR_EL1().FPEN != '11' then
        if EL2Enabled() && EffectiveTGEforEL0Traps() == '1' then
            AArch64_SystemAccessTrap(EL2, 0x00);
        else
            AArch64_SystemAccessTrap(EL1, 0x07);
        end;
    elsif EffectivelyAtEL0InHost() && CPTR_EL2().FPEN != '11' then
        AArch64_SystemAccessTrap(EL2, 0x07);
    elsif ELIsInHost(EL2) && CPTR_EL2().FPEN IN {'x0'} then
        AArch64_SystemAccessTrap(EL2, 0x07);
