        AArch64_SystemAccessTrap(EL2, 0x07);
    elsif HaveEL(EL3) && CPTR_EL3().TFP == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x07);
        end;
    else
        X{64}(t) = FPMR();
    end;
elsif PSTATE.EL == EL1 then
