        end;
    elsif !ELIsInHost(EL2) && CPTR_EL2().TFP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x07);
    elsif ELIsInHost(EL2) && CPTR_EL2().FPEN IN {'x0'} then
        AArch64_SystemAccessTrap(EL2, 0x07);
    elsif HaveEL(EL3) && CPTR_EL3().TFP == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
